select 'en', 'Painter', '', 'Someone who paints pictures: puts what they see onto the canvas.', '', 'رسّام', '', '', '🖌️', '', '', array['≠ Painter ≠ Artist']::text[], (select p.id from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com'), 0
where not exists (select 1 from public.words w where w.lang = 'en' and lower(w.headword) = lower('Painter'));
update public.words set tags = (select array(select distinct x from unnest(tags || array['≠ Painter ≠ Artist']) x order by x)) where id = (select id from public.words where lang = 'en' and lower(headword) = lower('Painter') order by (sense = '') desc limit 1);
insert into public.word_difference_parts (diff_key, word_id, explain, explain_ar, position) select 'painter-artist', w.id, 'Someone who paints pictures: puts what they see onto the canvas.', 'رسّام', 0 from public.words w where w.id = (select id from public.words where lang = 'en' and lower(headword) = lower('Painter') order by (sense = '') desc limit 1)
on conflict (diff_key, word_id) do update set explain = excluded.explain, explain_ar = excluded.explain_ar, position = excluded.position;
insert into public.set_entries (id, set_id, position, kind, unit, also_units, word_id, min_age)
select md5('diff:' || 'painter-artist' || ':' || w.id)::uuid, '00000000-0000-4000-8000-00000000d1ff', 1, 'term', 3, '{}', w.id, 0 from public.words w where w.id = (select id from public.words where lang = 'en' and lower(headword) = lower('Painter') order by (sense = '') desc limit 1)
and not exists (select 1 from public.set_entries e where e.set_id = '00000000-0000-4000-8000-00000000d1ff' and e.word_id = w.id)
