insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('past-history','Past ≠ History',3,0,'The past is what happened and is closed; history is the open page we still read and learn from.','الماضي مراحل وقضايا مضت وطويت صفحتها، أما التاريخ فصفحة مفتوحة مهما بلغ قدمها.','My past is my own; history is what everyone can learn from.',null,1) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
