insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('feeling-emotion-drive-sensation','Sensation ≠ Feeling ≠ Emotion ≠ Drive',1,10,'In everyday talk we mix them; in science they differ, and different parts of the brain handle them.','في اللغة نخلط بينها، لكن في الأوساط العلمية هناك فرق بين الحواس والإحساس والشعور والغريزة، ولكل منها مناطق في الدماغ.','Cold air on your skin is a sensation; feeling uneasy is a feeling; fear is an emotion; hunger is a drive.','Scientists use these terms in slightly different ways; this is a common way to separate them.',5) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
