insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('reward-bribe','Reward ≠ Bribe',3,0,'A reward thanks someone for effort after the good deed, from strength; a bribe pays someone to act for you or to stop something bad, from weakness.','المكافأة تقدير يُمنح عرفانًا بجهد أو إنجاز ويُقدّم في لحظة قوة؛ أما الرشوة فوسيلة لحثّ شخص على التصرف لصالحك أو استرجاء إيقاف عمل سيئ، وتُقدّم في لحظة ضعف.','"Well done, here''s a sticker" is a reward; "Stop crying and I''ll give you sweets" is a bribe.',null,6) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
