insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('suspicion-caution','Suspicion ≠ Caution',2,0,'Suspicion is a gut feeling (or, when constant, a problem); caution is a decision to trust only after experience.','الشك حدس أو مرض، أما عدم الوثوق إلا بالتجربة فهو قرار.','Checking a new friend''s promise is caution; believing everyone is lying is suspicion.',null,7) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
