insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('firm-rude','Firm ≠ Rude',3,0,'A strong personality is confident, clear and knows the limits, and can change its mind without losing respect; rudeness doesn''t care about others'' feelings and tries to put them down.','قوي الشخصية يملك الثقة والحزم والوضوح ومعرفة الحدود، والتراجع عن قراره لا يمس هيبته؛ أما قلة الأدب فعدم اكتراث بمشاعر الآخرين وسعي لإهانتهم برفع الصوت وحدّة النبرة.','"No, I won''t do that" said calmly is firm; shouting insults is rude.',null,8) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
