insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('hypersensitive-empathic','Hypersensitive ≠ Empathic',1,12,'Both are "sensitive", but in opposite directions: the hypersensitive person reads everything as being about themselves (praise or insult); the empathic person is sensitive to others.','الحساسية موجودة عند المضطربين والمتعاطفين؛ المضطرب حساسيته تجاه ذاته فيفسّر كل شيء إطراءً أو إهانة، والمتعاطف حساسيته تجاه الآخرين. والمفارقة أن المتلاعب يهوّن من أفعاله تجاه ضحيته بقوله: أنت حساس.','She noticed her friend was sad (empathic); he thought every joke was about him (hypersensitive).','Manipulators often dismiss their victims with "You''re too sensitive".',9) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
