insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('acceptance-indifference','Acceptance ≠ Indifference',1,10,'Acceptance takes part in life without trying to control everything, with hope and calm; indifference gives up, with despair. In a river: fighting the current is not accepting; swimming with it to safety is acceptance; letting it carry you away is indifference.','القبول هو الانخراط في الحياة دون محاولة إخضاعها ويرافقه أمل وهدوء؛ أما اللامبالاة فأهم سماتها اليأس. في النهر: السباحة ضد التيار عدم قبول، والسباحة معه نحو النجاة قبول، والاستسلام للمصير لامبالاة.','After losing the match she accepted it and trained harder; he just stopped caring.',null,10) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
