insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('explanation-justification','Explanation ≠ Justification',2,10,'Explaining says how and why something happened; justifying says it was right or acceptable.','التفسير يبيّن كيف ولماذا وقع الأمر، والتبرير يجعله مقبولًا؛ الباحث الجنائي يفسّر الجريمة من حيث الأداة والطريقة والدافع لكنه لا يبرّرها.','A detective explains how a crime happened but doesn''t justify it.',null,12) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
