insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('pleasure-happiness','Pleasure ≠ Happiness',1,0,'Pleasure is a short feeling; happiness is a lasting feeling that flows from inside.','اللذة شعور مؤقت، أما السعادة فشعور دائم متدفق من الداخل.','A sweet gives pleasure for a minute; a loving family gives happiness for years.','Popular science links pleasure with dopamine and calm well-being with serotonin; real brain chemistry is more mixed than that.',13) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
