insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('citizenship-nationality','Citizenship ≠ Nationality',4,12,'Citizenship (التابعية) is the legal tie between a person and a state; nationality is belonging to a nation or people.','التابعية كلمة دقيقة قانونيًا تعني أن المواطن تابع لهذه الدولة سياسيًا، والجنسية تعني أن تكون فردًا من أمة أو قومية.','His passport shows his citizenship; his nationality is the people he belongs to.','In everyday English the two words are often used the same way.',14) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
