insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('mood-depression-complaining','A low mood ≠ Depression ≠ A complaining habit',1,10,'A low mood passes; depression is a medical condition (low most days for weeks, with lost interest) that doctors can help; someone in hard times is reacting to real trouble; a chronic complainer complains about everything, from waking up early as a child to bills as an adult.','هناك فرق بين حالات مزاجية عابرة، وبين شخص دومًا مكتئب، وشخص يمر بظروف صعبة، وشخص دومًا متحلطم؛ المتحلطم الصغير يصبح متحلطمًا كبيرًا ثم عجوزًا.',null,null,36) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
