insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('organized-tidy','Organized ≠ Tidy',3,0,'Organizing places things in the best way to use them (efficiency); tidying puts them back in their places (how it looks).','التنظيم توزيع المحتويات التوزيع الأمثل لاستخدام كفؤ وهو دال على الكفاءة، أما الترتيب فالمحافظة على وضع الأشياء أماكنها ويتعلق بالمنظر.','I''m not always tidy, but I''m organized: I know where everything is.',null,38) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
