insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('projection-rationalization','Projection ≠ Rationalization',2,12,'Projection unconsciously sticks your own fault on others; rationalization is lying to yourself with good-sounding reasons. Arabs say: رمتني بدائها وانسلّت (she threw her own illness at me and slipped away).','الإسقاط آلية دفاعية يلصق فيها الشخص عيبه بالآخرين لا شعوريًا، أما التبرير فعملية كذب على النفس. تقول العرب: رمتني بدائها وانسلّت.','The lazy one calling others lazy is projection; "I skipped training because rest is healthy" is rationalization.',null,39) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
