insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('equity-equality','Equity ≠ Equality',4,10,'Equality gives everyone the same; equity gives each person what they need for a fair result.','المساواة تركّز على العدالة في التوزيع بغض النظر عن الفروقات، أما الإنصاف فيركّز على عدالة النتائج؛ المساواة لا تعني الإنصاف.','Same-size boxes for everyone to see over a fence is equality; different boxes so everyone can see is equity.',null,40) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
