insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('legal-legitimate','Legal ≠ Legitimate',4,12,'Legal means allowed by the law; legitimate means justified or acceptable. They usually match, but not always, and courts decide cases like self-defence.','هناك فرق بين المشروعية والشرعي (القانوني)؛ قد يكون لك حق الدفاع عن النفس، لكن الفعل نفسه يقيّمه القانون حسب الظروف.','Defending yourself can be legitimate; whether a particular act was legal is for a court to decide.',null,41) on conflict (key) do update set title=excluded.title, unit=excluded.unit, min_age=excluded.min_age, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
